import 'package:flutter/material.dart';import '../models/moment.dart';import '../services/moment_service.dart';import '../widgets/orbia_nav_bar.dart';import '../widgets/moment_form.dart';import 'timeline_screen.dart';import 'moments_screen.dart';import 'favorites_screen.dart';import 'archive_screen.dart';import 'search_screen.dart';import 'settings_screen.dart';
class HomeScreen extends StatefulWidget{final MomentService service;const HomeScreen({super.key,required this.service});@override State<HomeScreen> createState()=>_S();}
class _S extends State<HomeScreen>{int index=0;Future<void> create()async{final m=await showModalBottomSheet<Moment>(context:context,isScrollControlled:true,showDragHandle:true,builder:(_)=>const MomentFormSheet());if(m!=null)await widget.service.add(m);}
@override Widget build(BuildContext context){final pages=[TimelineScreen(service:widget.service),MomentsScreen(service:widget.service),FavoritesScreen(service:widget.service),ArchiveScreen(service:widget.service)];return Scaffold(extendBody:true,body:SafeArea(bottom:false,child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,16,12,4),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Orbia',style:Theme.of(context).textTheme.headlineLarge),const Text('Make every day worth the wait.',style:TextStyle(color:Color(0xFF77736F),fontWeight:FontWeight.w600))])),IconButton.filledTonal(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>SearchScreen(service:widget.service))),icon:const Icon(Icons.search_rounded)),IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>SettingsScreen(service:widget.service))),icon:const Icon(Icons.settings_outlined))])),Expanded(child:AnimatedSwitcher(duration:const Duration(milliseconds:240),child:KeyedSubtree(key:ValueKey(index),child:pages[index])))])),bottomNavigationBar:OrbiaNavBar(index:index,onChanged:(v)=>setState(()=>index=v),onCreate:create));}}
